export const catalogs=Object.freeze(Object.fromEntries(locales.map(locale=>{
  const allKeys=[...keys,...errorCodes,...activityKeys,...formKeys,...riskKeys,...walletKeys,...identityKeys,...confirmKeys],values=[...rows[locale],...errorRows[locale],...activityRows[locale],...formRows[locale],...riskRows[locale],...walletRows[locale],...identityRows[locale],...confirmRows[locale]];
  if(rows[locale].length!==keys.length||errorRows[locale].length!==errorCodes.length)throw new Error('EXCHANGE_LOCALE_CATALOG_INCOMPLETE');
  if(activityRows[locale].length!==activityKeys.length)throw new Error('EXCHANGE_ACTIVITY_CATALOG_INCOMPLETE');
  if(formRows[locale].length!==formKeys.length)throw new Error('EXCHANGE_FORM_CATALOG_INCOMPLETE');
  if(riskRows[locale].length!==riskKeys.length)throw new Error('EXCHANGE_RISK_CATALOG_INCOMPLETE');
  if(walletRows[locale].length!==walletKeys.length)throw new Error('EXCHANGE_WALLET_UI_CATALOG_INCOMPLETE');
  if(identityRows[locale].length!==identityKeys.length)throw new Error('EXCHANGE_IDENTITY_UI_CATALOG_INCOMPLETE');
  if(confirmRows[locale].length!==confirmKeys.length)throw new Error('EXCHANGE_CONFIRM_UI_CATALOG_INCOMPLETE');
  return [locale,Object.freeze(Object.fromEntries(allKeys.map((key,i)=>[key,values[i]])))];
})));
export const normalizeLocale=value=>locales.includes(value)?value:'en';
export const translate=(locale,key)=>catalogs[normalizeLocale(locale)][key]??key;

export function installExchangeLocale({document,storage,onChange=()=>{}}){
  let locale='en';try{locale=normalizeLocale(storage?.getItem('ynx-exchange-language'))}catch{}
  const messages=new Map();
  const api={
    locale:()=>locale,
    text:key=>translate(locale,key),
    write(element,key,suffix=''){if(!element)return;messages.set(element,{key,suffix});element.textContent=translate(locale,key)+suffix},
    forget(element){messages.delete(element)},
    error(element,error){if(!element||!errorCodes.includes(error?.code))return false;api.write(element,error.code,` (${error.code})`);return true},
    set(value){locale=normalizeLocale(value);try{storage?.setItem('ynx-exchange-language',locale)}catch{}apply();onChange(locale);return locale}
  };
  function apply(){
    document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';
    for(const element of document.querySelectorAll('[data-exchange-locale]'))element.textContent=translate(locale,element.dataset.exchangeLocale);
    const activityLabels={trades:'Trade history',orders:'Order history',ledger:'Asset ledger',deposits:'Deposits',withdrawals:'Withdrawals',fees:'Fee history',audit:'Audit'};
    for(const element of document.querySelectorAll('[data-activity]'))element.textContent=translate(locale,activityLabels[element.dataset.activity]);
    const formLabels={'#buy-tab':'Buy','#sell-tab':'Sell','#draft-order':'Ask AI to draft fields','#review-order':'Preview order · no submission','#order-preview-title':'Review a limit order','#order-preview-dialog .wide':'Return to edit'};
    for(const [selector,key] of Object.entries(formLabels)){const element=document.querySelector(selector);if(element)element.textContent=translate(locale,key)}
    const walletLabels={'#connect':'Connect YNX Wallet','#wallet-dialog h2':'Choose a Wallet','#connect-ynx-wallet':'Installed YNX Wallet','#wallet-retry':'Reconnect selected wallet','#wallet-disconnect':'Disconnect locally','#wallet-revoke':'Revoke account permission…','#wallet-switch':'Switch wallet','#wallet-fallback a:first-child':'Download YNX Wallet','#wallet-fallback a:last-child':'Use MetaMask'};
    for(const [selector,key] of Object.entries(walletLabels)){const element=document.querySelector(selector);if(element)element.textContent=translate(locale,key)}
    for(const [i,key] of ['Provider:','Account:','Network:'].entries()){const element=document.querySelectorAll('#wallet-details strong')[i];if(element)element.textContent=translate(locale,key)}
    const boundary=document.querySelector('#wallet-details p:nth-last-of-type(1)');if(boundary)boundary.textContent=translate(locale,'wallet-local-boundary');
    for(const [element,{key,suffix}]of messages){if(element.isConnected)element.textContent=translate(locale,key)+suffix;else messages.delete(element)}
    const selector=document.querySelector('#exchange-language');if(selector)selector.value=locale;
  }
  const selector=document.querySelector('#exchange-language');selector?.addEventListener('change',()=>api.set(selector.value));
  apply();return Object.freeze(api);
}
